def largest_smallest_integers(lst: List[int]) -> Tuple[Optional[int], Optional[int]]:
    if not lst:
        return (None, None)

    max_neg = -float('inf')
    min_pos = float('-inf')

    for num in lst:
        if num < 0:
            max_neg = max(max_neg, num)
        else:
            min_pos = min(min_pos, num)

